// GetDataParams defines parameters for GetData.
type GetDataParams struct {
	Page  *int `form:"page,omitempty" json:"page,omitempty"`
	Limit *int `form:"limit,omitempty" json:"limit,omitempty"`

	// AnchorRowID Return the page containing this row under the same filters and ordering. Overrides page; the response includes the one-based resolved page. Returns 404 if the row is absent from the filtered rows. Requires limit >= 1.
	AnchorRowID       *int `form:"anchor_row_id,omitempty" json:"anchor_row_id,omitempty"`
	DataSourceModelID *int `form:"data_source_model_id,omitempty" json:"data_source_model_id,omitempty"`
	AlertItemID       *struct {
		union json.RawMessage
	} `form:"alert_item_id,omitempty" json:"alert_item_id,omitempty"`
	WarningItemID *int  `form:"warning_item_id_,omitempty" json:"warning_item_id_,omitempty"`
	HasAnyWarning *bool `form:"has_any_warning,omitempty" json:"has_any_warning,omitempty"`

	// ProblemKind Problem group filter: the issue kind of the group. Requires problem_issue_type. With neither problem_dataset_rule_id nor problem_field_names, the group is the whole-row issues of the type (no rule, no field). Only valid when is_bad_data=True; otherwise 400.
	ProblemKind *ProblemKind `form:"problem_kind,omitempty" json:"problem_kind,omitempty"`

	// ProblemIssueType Problem group filter: the alert or warning type of the group; 400 when it is not a type of problem_kind. Only valid when is_bad_data=True; otherwise 400.
	ProblemIssueType *string `form:"problem_issue_type,omitempty" json:"problem_issue_type,omitempty"`

	// ProblemDatasetRuleID Problem group filter: the dataset rule of a rule group. Not with problem_field_names. Only valid when is_bad_data=True; otherwise 400.
	ProblemDatasetRuleID *openapi_types.UUID `form:"problem_dataset_rule_id,omitempty" json:"problem_dataset_rule_id,omitempty"`

	// ProblemFieldNames Problem group filter: the field names of a group without a rule; empty for a whole-row group. Not with problem_dataset_rule_id. Only valid when is_bad_data=True; otherwise 400.
	ProblemFieldNames *[]string `form:"problem_field_names,omitempty" json:"problem_field_names,omitempty"`
	StoredItemID      *int      `form:"stored_item_id,omitempty" json:"stored_item_id,omitempty"`

	// DeletedRows Which rows to return. live: rows that are not deleted. live_and_person_deleted: also quarantine rows a person deleted or erased, or that an earlier delete excluded. all: every row, deleted or not.
	DeletedRows        *DeletedRows `form:"deleted_rows,omitempty" json:"deleted_rows,omitempty"`
	AwaitingProcessing *bool        `form:"awaiting_processing_,omitempty" json:"awaiting_processing_,omitempty"`

	// QuarantineHold Filter quarantine rows by their keep-in-quarantine decision: `hold` (kept in quarantine even when valid), `release` (explicitly released for reprocessing) or `undecided` (the dataset's quarantine policy decides). Only valid when is_bad_data=True; otherwise 400. Absent = no filter.
	QuarantineHold *QuarantineHold `form:"quarantine_hold,omitempty" json:"quarantine_hold,omitempty"`

	// HeldForApproval true: only quarantine rows held for approval (no keep-in-quarantine decision and a non-null approval_hold_reasons entry, outside requests); false: every other quarantine row. Only valid when is_bad_data=True; otherwise 400. Absent = no filter.
	HeldForApproval *bool `form:"held_for_approval,omitempty" json:"held_for_approval,omitempty"`

	// WaitingForApproval true: only undecided quarantine rows in a non-closed submitted data review; false: every other quarantine row. Only valid when is_bad_data=True; otherwise 400. Absent = no filter.
	WaitingForApproval *bool `form:"waiting_for_approval,omitempty" json:"waiting_for_approval,omitempty"`

	// ApprovalHoldReason Only quarantine rows whose approval_hold_reasons entry is this value, whatever their keep-in-quarantine decision. Combine with held_for_approval=true for the rows held for approval for this reason. Only valid when is_bad_data=True; otherwise 400. Absent = no filter.
	ApprovalHoldReason  *ApprovalHoldReason `form:"approval_hold_reason,omitempty" json:"approval_hold_reason,omitempty"`
	PassesValidation    *bool               `form:"passes_validation_,omitempty" json:"passes_validation_,omitempty"`
	IsBadData           *bool               `form:"is_bad_data,omitempty" json:"is_bad_data,omitempty"`
	ShowMetadata        *bool               `form:"show_metadata,omitempty" json:"show_metadata,omitempty"`
	ShowRowLogs         *bool               `form:"show_row_logs,omitempty" json:"show_row_logs,omitempty"`
	IncludeHistoryFlags *bool               `form:"include_history_flags,omitempty" json:"include_history_flags,omitempty"`

	// DatasetRuleIds Filter quarantine rows whose dataset_rule_ids_ array overlaps any of these UUIDs. Only valid when is_bad_data=True; otherwise 400.
	DatasetRuleIds        *[]openapi_types.UUID `form:"dataset_rule_ids_,omitempty" json:"dataset_rule_ids_,omitempty"`
	IncludeDatasetRuleIds *bool                 `form:"include_dataset_rule_ids,omitempty" json:"include_dataset_rule_ids,omitempty"`
	FilterByFieldName     *string               `form:"filter_by_field_name,omitempty" json:"filter_by_field_name,omitempty"`
	FilterByFieldValue    *string               `form:"filter_by_field_value,omitempty" json:"filter_by_field_value,omitempty"`
	SearchQuery           *string               `form:"search_query,omitempty" json:"search_query,omitempty"`
	SearchByFieldName     *string               `form:"search_by_field_name,omitempty" json:"search_by_field_name,omitempty"`
	FilterOperator        *FilterOperator       `form:"filter_operator,omitempty" json:"filter_operator,omitempty"`

	// OrderBy order by these field names
	OrderBy *[]string `form:"order_by,omitempty" json:"order_by,omitempty"`

	// HistoryIds filter by rows that have these history ids
	HistoryIds *[]int `form:"history_ids_,omitempty" json:"history_ids_,omitempty"`

	// CommentThreadID filter to the rows targeted by this comment thread
	CommentThreadID *openapi_types.UUID `form:"comment_thread_id,omitempty" json:"comment_thread_id,omitempty"`

	// Fields limit to these fields
	Fields *[]string `form:"fields,omitempty" json:"fields,omitempty"`

	// ReviewChangeHistoryID Only rows where this submitted change is still the live latest-per-field gate entry of an ACTIVE data review (ask I). 422 unless is_bad_data=true.
	ReviewChangeHistoryID *int `form:"review_change_history_id,omitempty" json:"review_change_history_id,omitempty"`

	// ReviewStatus Server-side row-level review-state filter (Wave-2 §7.2). Only valid when is_bad_data=true; otherwise 400. accepted/rejected/awaiting_decision = disjoint gate-verdict buckets.
	ReviewStatus *ReviewStatusFilter `form:"review_status,omitempty" json:"review_status,omitempty"`

	// ReviewGroupID Scope the bad rows to one submission (ReviewGroup): only rows with a non-closed review in this group. Only valid when is_bad_data=True; otherwise 400. Absent = no filter.
	ReviewGroupID *openapi_types.UUID `form:"review_group_id,omitempty" json:"review_group_id,omitempty"`

	// RequestState Request progress state. Requires is_bad_data=true and review_group_id. Approver: to_review, flagged_by_me, approved, on_hold. Sender: waiting, flagged, approved, on_hold. Precedence: on_hold, active flag, approved, pending.
	RequestState *RequestStateFilter `form:"request_state,omitempty" json:"request_state,omitempty"`
	RequestView  *RequestView        `form:"request_view,omitempty" json:"request_view,omitempty"`

	// MaxCellChars Truncate returned text/json/array cell values to at most this many characters (SQL-side). Truncated cells are listed in truncated_cells as [row_index, field_name] pairs.
	MaxCellChars *int `form:"max_cell_chars,omitempty" json:"max_cell_chars,omitempty"`

	// FullValues Disable read-side truncation. Only allowed for narrow requests: explicit `fields` and limit <= 2; otherwise 422.
	FullValues *bool `form:"full_values,omitempty" json:"full_values,omitempty"`

	// SearchRegex Match search_query as a Python `re` regex (parity with search-and-replace). Casts columns to text; disables the trigram/exact fast path.
	SearchRegex *bool `form:"search_regex,omitempty" json:"search_regex,omitempty"`

	// SearchCaseSensitive Match search_query case-sensitively.
	SearchCaseSensitive *bool `form:"search_case_sensitive,omitempty" json:"search_case_sensitive,omitempty"`

	// SearchWholeValue Match the complete displayed cell value instead of a substring.
	SearchWholeValue *bool `form:"search_whole_value,omitempty" json:"search_whole_value,omitempty"`

	// SearchTimezone IANA name of the timezone a date search term is read in (e.g. America/Los_Angeles). A Date or DateTime column is matched as the half-open UTC range the term names, so the viewer's timezone decides which rows a day term covers. Absent = UTC. Date columns carry no timezone and ignore it.
	SearchTimezone *string `form:"search_timezone,omitempty" json:"search_timezone,omitempty"`
	OauthSession   *string `form:"oauth_session,omitempty" json:"oauth_session,omitempty"`
}

